def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release (everything after '-')
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            pre_identifiers = prerelease.split('.')
            # Convert all-digit identifiers to integers for numeric comparison
            pre_parts = []
            for identifier in pre_identifiers:
                if identifier.isdigit():
                    pre_parts.append((0, int(identifier)))  # 0 means numeric, sorts first
                else:
                    pre_parts.append((1, identifier))  # 1 means string, sorts after numeric
        else:
            pre_parts = None

        return (major, minor, patch, pre_parts)

    def sort_key(item):
        index, v = item
        major, minor, patch, pre_parts = parse_version(v)

        # For sorting: version with pre-release sorts before version without
        # If pre_parts is None, use a tuple that sorts after any pre-release
        if pre_parts is None:
            pre_sort = (1,)  # Sorts after pre-release (0, ...)
        else:
            pre_sort = (0, tuple(pre_parts))  # Sorts before release (1,)

        return (major, minor, patch, pre_sort, index)

    # Sort with stable sort to maintain input order for equal precedence
    indexed_versions = list(enumerate(versions))
    indexed_versions.sort(key=sort_key)

    return [v for _, v in indexed_versions]

